window.DATA.appstore = {"tags": ["Differentialdiagnosen", "F0 – Organische Störungen", "F1 – Substanzstörungen", "F2 – Schizophrenie", "F3 – Affektive Störungen", "F4 – Neurotische Störungen", "F5 – Verhaltensauffälligkeiten", "F6 – Persönlichkeitsstörungen", "F7-F9 – Entwicklung & Kindheit", "ICD-10 Grundlagen", "Psychopathologie", "Recht & Berufskunde", "Therapieverfahren"], "qterms": [["Benzodiazepine", "Angstlösende, beruhigende, schlaffördernde und krampflösende Medikamente; Abhängigkeitsrisiko"], ["LSD", "Lysergsäurediethylamid – Halluzinogen; Risiko von Horrortrip und Flashbacks, keine körperliche Abhängigkeit"], ["Opioid", "Opiate (aus Opium: Morphin, Codein) und Opioide (halbsynthetisch z. B. Heroin, synthetisch z. B. Fentanyl, Methadon, Tramadol): Schmerzlinderung, Euphorie, Sedierung. Überdosierung: Trias Koma, Atemdepression, stecknadelkopfgroße Pupillen – Gegenmittel Naloxon. Substitutionsbehandlung mit Methadon."]], "glossCount": 359, "montage": [{"num": 11, "q": "Unter Zerfahrenheit versteht man in der Psychotherapie:", "options": ["Das phänomenologische Bild der Parathymie", "Eine formale Denkstörung", "Eine Aufmerksamkeitsstörung", "Eine Störung der Affektivität", "Eine Bewusstseinsstörung"], "correct": 1, "wrong": null, "expl": "Zerfahrenheit (Inkohärenz) ist eine formale Denkstörung. Sie bezeichnet einen Zustand, bei dem der Zusammenhang zwischen den einzelnen Gedanken verloren geht – das Denken wirkt zusammenhanglos und unverständlich. Zerfahrenheit tritt typischerweise bei der Schizophrenie auf und ist keine Affektstörung, Aufmerksamkeitsstörung oder Bewusstseinsstörung."}, {"num": 16, "q": "Welches Symptom lässt am ehesten an eine beginnende Demenz denken?", "options": ["Gangstörung", "Affektive Veränderung", "Paranoider Wahn", "Bewusstseinsverschiebung", "Stuhl- und Harninkontinenz"], "correct": 1, "wrong": null, "expl": "Affektive Veränderungen (z.B. Reizbarkeit, Stimmungsschwankungen, Apathie, depressive Verstimmung) gehören zu den frühesten Symptomen einer beginnenden Demenz, noch bevor ausgeprägte kognitive Defizite offensichtlich werden. Gangstörungen (A) und Inkontinenz (E) treten eher in fortgeschrittenen Stadien auf. Paranoider Wahn (C) kann auftreten, ist aber nicht das typische Frühsymptom. Bewusstseinsverschiebung (D) ist kein typisches Demenzsymptom."}, {"num": 21, "q": "Welche Substanz verursacht im Rahmen des Konsums eine Miosis?", "options": ["Amphetamine", "Opioide/Opiate", "Kokain", "Psilocybin", "Cannabis"], "correct": 1, "wrong": 2, "expl": "Opioide/Opiate verursachen eine Miosis (Pupillenverengung) – sogenannte Stecknadelpupillen sind ein Leitsymptom der Opiatintoxikation. Amphetamine (A), Kokain (C), Psilocybin (D) und Cannabis (E) verursachen hingegen eine Mydriasis (Pupillenerweiterung)."}, {"num": 25, "q": "Welches der folgenden Symptome gehört zu den Ich-Störungen?", "options": ["Sprachverarmung", "Apathie", "Gedankenabriss", "Gedankenentzug", "Negativismus"], "correct": 3, "wrong": null, "expl": "Der Gedankenentzug gehört zu den Ich-Störungen: Der Betroffene erlebt, dass ihm Gedanken von außen weggenommen werden. Weitere Ich-Störungen sind Gedankeneingebung, Gedankenausbreitung, Willensbeeinflussung, Depersonalisation und Derealisation. Gedankenabriss ist demgegenüber eine formale Denkstörung (der Gedankengang bricht ohne Fremdeinwirkung ab), Sprachverarmung und Apathie sind Negativsymptome, Negativismus ist ein katatones Symptom."}, {"num": 28, "q": "Grübeln gehört im psychopathologischen Befund zur Gruppe der:", "options": ["Aufmerksamkeits- und Gedächtnisstörungen", "Formalen Denkstörungen", "Befürchtungen und Zwänge", "Ich-Störungen", "Inhaltlichen Denkstörungen"], "correct": 1, "wrong": null, "expl": "Grübeln wird im psychopathologischen Befund den formalen Denkstörungen zugeordnet. Es handelt sich um ein ständiges Beschäftigtsein mit (oft unangenehmen) Gedanken, die nicht produktiv weiterführen – eine Störung des Denkablaufs. Es ist kein inhaltlicher Wahn, keine Ich-Störung und keine reine Aufmerksamkeitsstörung."}, {"num": 30, "q": "Welches Merkmal gehört typischerweise nicht zur paranoiden Persönlichkeitsstörung?", "options": ["Abhängigkeit von der Meinung Anderer", "Empfindlichkeit", "Misstrauen", "Selbstbezogenheit", "Streitsucht"], "correct": 0, "wrong": null, "expl": "Abhängigkeit von der Meinung Anderer gehört nicht zur paranoiden Persönlichkeitsstörung, sondern eher zur dependenten oder ängstlich-vermeidenden PS. Die paranoide PS ist gekennzeichnet durch übermäßiges Misstrauen, Empfindlichkeit gegenüber Zurückweisung, Selbstbezogenheit und Streitsucht. Paranoide Persönlichkeiten sind gerade nicht von anderen abhängig, sondern eher misstrauisch und eigenbrötlerisch."}]};
window.DATA.glossList = {"head": [["Abhängigkeitssyndrom", "ICD-10 (F1x.2): mind. 3 von 6 Kriterien gleichzeitig über mind. 1 Monat oder wiederholt innerhalb von 12 Monaten – starkes Verlangen (Craving), verminderte Kontrollfähigkeit (Kontrollverlust), körperliches Entzugssyndrom, Toleranzentwicklung, Vernachlässigung anderer Interessen, fortgesetzter Konsum trotz schädlicher Folgen."], ["Absetzphänomene", "Beschwerden nach abruptem Absetzen (z.B. von SSRI) – kein Hinweis auf Abhängigkeit, daher ausschleichen"], ["Abstinenzregel", "Verbot privater/sexueller Beziehungen zum Patienten – auch nach Therapieende"], ["Abwehrmechanismen", "Unbewusste Strategien des Ichs zur Konfliktbewältigung (z.B. Verdrängung, Projektion, Regression)"], ["Acetylcholin", "Neurotransmitter an der motorischen Endplatte, im Parasympathikus und im ZNS (u. a. Gedächtnis)"], ["ADHS", "Aufmerksamkeitsdefizit-/Hyperaktivitätsstörung: Unaufmerksamkeit, Hyperaktivität und Impulsivität mit Beginn in der Kindheit; ADS = vorwiegend unaufmerksamer Subtyp ohne Hyperaktivität."], ["Adynamie", "Antriebs- und Kraftlosigkeit – abzugrenzen von der Akathisie mit Bewegungsdrang"], ["Affektinkontinenz", "Affekte können nicht beherrscht werden; schon geringe Anlässe lösen heftige Gefühlsausbrüche aus"], ["affektive Störungen", "Störungen mit krankhafter Veränderung von Stimmung und Antrieb (Depression, Manie, bipolare Störung)"], ["Affektlabilität", "Rascher, oft unmotivierter Wechsel der Stimmung"], ["Affektverflachung", "Verminderte Anzahl, Intensität und Bandbreite gezeigter Gefühle (auch Affektarmut; Negativsymptom)."], ["Aggressionsumkehr", "aggressive Impulse richten sich gegen die eigene Person"]], "anhedonie": ["Anhedonie", "Unfähigkeit, Freude oder Lust zu empfinden"]};

